import { useQueryClient } from '@tanstack/react-query';

function UserBadge({ userId }: { userId: string }) {
  const queryClient = useQueryClient();

  // Read the users list from cache â€” no fetch triggered
  const usersCache = queryClient.getQueryData<string[]>(['users']);
  const user = usersCache?.find(u => u.id === userId);

  if (!user) return <span>Unknown user</span>;
  return <span>{user.name}</span>;
}

import { useQueryClient } from '@tanstack/react-query';

function AddUserForm() {
  const queryClient = useQueryClient();

  const handleSubmit = async (name: string) => {
    const newUser = await createUserOnServer(name);

    // Immediately update the cached users list
    queryClient.setQueryData<string[]>(['users'], (old = []) => {
      return [...old, newUser];
    });
  };

  return <form onSubmit={handleSubmit}>{/* form fields */}</form>;
}

